          <Route path="/checkout" element={<Checkout />} />
          <Route path="/login" element={<Login />} />
          <Route path="/thank-you" element={<ThankYou />} />
          {/* TODO(dev2): add admin routes here e.g. <Route path="/admin/*" element={<AdminDashboard />} /> */}
